import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import API from '../api';

export default function ClientDetail() {
  const { id } = useParams();
  const [client, setClient] = useState(null);
  const [activeImg, setActiveImg] = useState(null);

  useEffect(() => {
    API.get(`/clients/${id}`).then((r) => setClient(r.data));
  }, [id]);

  if (!client) return <div style={{ textAlign: 'center', padding: 80, color: '#a3a3a3' }}>Loading...</div>;

  return (
    <div style={{ maxWidth: 1000, margin: '0 auto', padding: '60px 24px' }}>
      <Link to="/clients" style={{ color: '#a3a3a3', fontSize: 14 }}>← Back to Clients</Link>

      <div style={{ display: 'flex', alignItems: 'center', gap: 20, margin: '32px 0 24px' }}>
        <div style={{ width: 80, height: 80, background: 'linear-gradient(135deg,#f97316,#fb923c)', borderRadius: 20, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 40 }}>
          {client.icon}
        </div>
        <div>
          <h1 style={{ fontSize: 32, fontWeight: 900 }}>{client.name}</h1>
          <span style={{ background: '#f9731620', color: '#f97316', padding: '4px 12px', borderRadius: 20, fontSize: 13 }}>{client.category}</span>
        </div>
      </div>

      <p style={{ color: '#a3a3a3', fontSize: 16, lineHeight: 1.8, marginBottom: 32 }}>{client.full_description}</p>

      {/* Stats */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 16, marginBottom: 32 }}>
        {[['📅', 'Established', client.established], ['📍', 'Location', client.location], ['👥', 'Followers', client.followers], ['📈', 'Growth', client.growth]].map(([icon, l, v]) => (
          <div key={l} style={{ background: '#171717', border: '1px solid #262626', borderRadius: 14, padding: 16 }}>
            <div style={{ fontSize: 20, marginBottom: 6 }}>{icon}</div>
            <div style={{ color: '#a3a3a3', fontSize: 12 }}>{l}</div>
            <div style={{ fontWeight: 700, marginTop: 2 }}>{v || '—'}</div>
          </div>
        ))}
      </div>

      {/* License */}
      <div style={{ background: '#171717', border: '2px solid #22c55e40', borderRadius: 16, padding: 20, marginBottom: 32, display: 'flex', alignItems: 'center', gap: 16 }}>
        <div style={{ width: 48, height: 48, background: '#22c55e', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 22 }}>✓</div>
        <div>
          <div style={{ color: '#22c55e', fontWeight: 700 }}>Verified Licensed Business</div>
          <div style={{ color: '#a3a3a3', fontSize: 13 }}>License: {client.license_number || '—'}</div>
        </div>
      </div>

      {/* Images */}
      {client.images?.length > 0 && (
        <div style={{ marginBottom: 40 }}>
          <h2 style={{ fontSize: 22, fontWeight: 800, marginBottom: 16 }}>Our Marketing Work</h2>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: 14 }}>
            {client.images.map((img) => (
              <div key={img.id} onClick={() => setActiveImg(img.url)} style={{ cursor: 'zoom-in', borderRadius: 12, overflow: 'hidden', aspectRatio: '4/3' }}>
                <img src={img.url} alt={img.description} style={{ width: '100%', height: '100%', objectFit: 'cover', transition: 'transform 0.3s' }} />
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Videos */}
      {client.videos?.length > 0 && (
        <div style={{ marginBottom: 40 }}>
          <h2 style={{ fontSize: 22, fontWeight: 800, marginBottom: 16 }}>Video Content</h2>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
            {client.videos.map((v, i) => (
              <div key={v.id} style={{ background: '#171717', border: '1px solid #262626', borderRadius: 14, padding: 16, display: 'flex', alignItems: 'center', gap: 16 }}>
                <div style={{ width: 64, height: 64, background: '#f9731620', borderRadius: 12, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 28 }}>▶</div>
                <div>
                  <div style={{ color: '#f97316', fontSize: 12, fontWeight: 600 }}>Video {i + 1}</div>
                  <div style={{ fontWeight: 600, marginTop: 2 }}>{v.description}</div>
                  <a href={v.url} target="_blank" rel="noreferrer" style={{ color: '#a3a3a3', fontSize: 13 }}>Watch ↗</a>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Lightbox */}
      {activeImg && (
        <div onClick={() => setActiveImg(null)} style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.95)', zIndex: 9999, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'zoom-out' }}>
          <img src={activeImg} alt="" style={{ maxWidth: '90vw', maxHeight: '90vh', objectFit: 'contain', borderRadius: 12 }} />
          <button onClick={() => setActiveImg(null)} style={{ position: 'absolute', top: 20, right: 24, background: 'none', border: 'none', color: '#fff', fontSize: 32, cursor: 'pointer' }}>✕</button>
        </div>
      )}
    </div>
  );
}
